---
--- title: Maximum value in an int array
--- description: Walk an arr[int] with a while loop, comparing each element to a running maximum.
--- expected_output: |
---   9
--- tags: [arrays, indexing, len]
---

int main() {
    arr[int] nums := [3, 1, 4, 1, 5, 9, 2, 6];
    mut int max_val := nums[0];
    mut int i := 1;
    while i < len(nums) {
        if nums[i] > max_val { max_val = nums[i]; }
        i = i + 1;
    }
    print_int(max_val);
    println();
    return 0;
}

---
--- title: Bitwise flag pack and unpack
--- description: Set two flags by OR-ing 1 and 2, then test each bit with & and a shift.
--- expected_output: |
---   flag_a: 1
---   flag_b: 1
--- tags: [bitwise, operators]
---

int main() {
    int packed := 1 | 2;
    int flag_a := packed & 1;
    int flag_b := (packed >> 1) & 1;
    print_str("flag_a: "); print_int(flag_a); println();
    print_str("flag_b: "); print_int(flag_b); println();
    return 0;
}

---
--- title: Combining conditions with &&
--- description: Use && to require two conditions both hold. The result is true only when both sides are true.
--- expected_output: |
---   both positive
--- tags: [bool, logic, operators]
---

int main() {
    int a := 3;
    int b := 4;
    if a > 0 && b > 0 {
        print_str("both positive");
    } else {
        print_str("at least one non-positive");
    }
    println();
    return 0;
}

