--- title: Echo an integer from stdin
--- description: Reads one int with read_int and prints it back.
--- stdin: |
---   42
--- expected_output: |
---   42
--- tags: [io, read_int]
---

int main() {
    int n := read_int();
    print_int(n);
    println();
    return 0;
}

---
--- title: Euclidean GCD via recursion
--- description: Greatest common divisor with the standard recurrence: gcd(a, 0) = a; gcd(a, b) = gcd(b, a % b).
--- expected_output: |
---   14
--- tags: [recursion, modulo, algorithms]
---

int gcd(int a, int b) {
    if b == 0 { return a; } else { return gcd(b, a % b); }
}

int main() {
    print_int(gcd(98, 56));
    println();
    return 0;
}

---
--- title: Swap two ints via &mut
--- description: A swap function takes two &mut int parameters and exchanges the values they point to. The caller prints x then y before and after.
--- expected_output: |
---   before: 1 2
---   after: 2 1
--- tags: [references, mutability]
---

int swap(&mut int a, &mut int b) {
    int tmp := *a;
    *a = *b;
    *b = tmp;
    return 0;
}

int main() {
    mut int x := 1;
    mut int y := 2;
    print_str("before: ");
    print_int(x); print_str(" "); print_int(y); println();
    swap(&mut x, &mut y);
    print_str("after: ");
    print_int(x); print_str(" "); print_int(y); println();
    return 0;
}

