--- title: print_str with multiple lines
--- description: Print a two-line greeting using print_str and println.
--- expected_output: |
---   hello, world!
---   how are you?
--- tags: [strings, print_str]
---

int main() {
    print_str("hello, world!");
    println();
    print_str("how are you?");
    println();
    return 0;
}

---
--- title: Sum of a range
--- description: Iterate 0..n with for-in, accumulating into a mut int.
--- expected_output: |
---   45
--- tags: [for-in, mutability]
---

int sum_to(int n) {
    mut int total := 0;
    for i in 0..n { total = total + i; }
    return total;
}

int main() {
    print_int(sum_to(10));
    println();
    return 0;
}
